<?php
$common=['theme'=>'dark','density'=>'compact','notify_orders'=>'1','notify_reviews'=>'1','notify_verification'=>'1','notify_stock'=>'1'];
$buyerPrefs=$common+['catalog_sort'=>'price-asc','preferred_categories'=>[1,3]];
$market->savePreferences($retailer,$buyerPrefs);
check(preferences(1)['theme']==='dark' && preferences(1)['density']==='compact','appearance settings persist');
check(preferences(1)['preferred_categories']===[1,3],'retailer category preferences persist');
denied(fn()=>$market->savePreferences($retailer,array_replace($buyerPrefs,['preferred_categories'=>[999999]])),'invalid preferred category rejected');
denied(fn()=>$market->savePreferences($retailer,array_replace($buyerPrefs,['theme'=>'invalid'])),'invalid appearance option rejected');
$before=(int)row('SELECT COUNT(*) AS n FROM notifications WHERE user_id=1')['n'];
$muted=$buyerPrefs;unset($muted['notify_orders']);$market->savePreferences($retailer,$muted);$market->notify(1,'Muted order event');
check((int)row('SELECT COUNT(*) AS n FROM notifications WHERE user_id=1')['n']===$before,'disabled order alerts are not created');
$market->notify(1,'Verification event','verification');
check((int)row('SELECT COUNT(*) AS n FROM notifications WHERE user_id=1')['n']===$before+1,'enabled notification type remains active');
$supplierPrefs=$common+['low_stock_threshold'=>5,'default_minimum_quantity'=>12,'company_description'=>'Trusted components','contact_email'=>'sales@example.test','contact_phone'=>'+63 900 000 0000','business_hours'=>'Mon–Fri, 9–5'];
$market->savePreferences($supplier,$supplierPrefs);
check(preferences(2)['default_minimum_quantity']===12 && preferences(2)['contact_email']==='sales@example.test','supplier inventory defaults and contact details persist');
denied(fn()=>$market->savePreferences($supplier,array_replace($supplierPrefs,['low_stock_threshold'=>-1])),'negative low-stock threshold rejected');
denied(fn()=>$market->savePreferences($supplier,array_replace($supplierPrefs,['contact_email'=>'bad'])),'invalid public contact email rejected');
$market->saveProduct($supplier,['name'=>'Settings test item','sku'=>'SETTINGS-TEST','description'=>'Stock alert testing','price'=>'5.00','minimum_quantity'=>1,'stock'=>20,'category_id'=>6,'brand_id'=>6]);
$stockId=(int)row("SELECT id FROM products WHERE sku='SETTINGS-TEST'")['id'];
$alertCount=fn()=>(int)row("SELECT COUNT(*) AS n FROM notifications WHERE user_id=2 AND message LIKE 'Low stock: Settings test item%' ")['n'];
$setStock=function(int $quantity)use($market,$stockId){$market->transaction(function()use($market,$stockId,$quantity){execute('UPDATE inventory SET stock=? WHERE product_id=?',[$quantity,$stockId]);$market->checkLowStock($stockId);});};
$setStock(5);check($alertCount()===1,'threshold crossing generates stock alert');
$setStock(4);check($alertCount()===1,'stock alerts do not repeat while below threshold');
$setStock(8);$setStock(2);check($alertCount()===2,'replenishment rearms stock alert');
$noStock=$supplierPrefs;unset($noStock['notify_stock']);$market->savePreferences($supplier,$noStock);$setStock(9);$setStock(0);check($alertCount()===2,'disabled stock alerts remain quiet');
$market->savePreferences($supplier,$supplierPrefs);check($alertCount()===3,'reenabling stock alerts checks current stock');
$tax=['kind'=>'category','name'=>'New settings category'];
denied(fn()=>$market->saveTaxonomy($retailer,$tax),'retailer cannot manage categories');
$market->saveTaxonomy($admin,$tax);$catId=(int)row("SELECT id FROM categories WHERE name='New settings category'")['id'];
$market->saveTaxonomy($admin,['kind'=>'category','id'=>$catId,'name'=>'Renamed settings category']);check((bool)row("SELECT id FROM categories WHERE name='Renamed settings category'"),'administrator can rename category');
denied(fn()=>$market->saveTaxonomy($admin,['kind'=>'category','id'=>1,'operation'=>'delete']),'used categories cannot be removed');
$market->saveTaxonomy($admin,['kind'=>'category','id'=>$catId,'operation'=>'delete']);check(!row('SELECT id FROM categories WHERE id=?',[$catId]),'administrator can remove unused category');
$market->saveTaxonomy($admin,['kind'=>'brand','name'=>'New settings brand']);check((bool)row("SELECT id FROM brands WHERE name='New settings brand'"),'administrator can add brand');
denied(fn()=>$market->saveDocumentRequirements($supplier,['required_documents'=>'Tax certificate']),'supplier cannot change document requirements');
$market->saveDocumentRequirements($admin,['required_documents'=>"Business registration\nTax certificate"]);
check(count(requiredDocuments())===2,'required document types persist');
denied(fn()=>$market->verifySupplier($admin,5,'verified',''),'approval requires all configured document types');
execute('INSERT INTO supplier_documents(supplier_id,document_type,original_name,stored_name,mime_type) VALUES (5,?,?,?,?)',['Tax certificate','tax.pdf','test-tax-fixture','application/pdf']);
$market->verifySupplier($admin,5,'verified','All required types present');check(row('SELECT verification_status FROM suppliers WHERE user_id=5')['verification_status']==='verified','complete document set permits approval');
$_SESSION=['user_id'=>2,'session_version'=>0];check(currentUser()!==null,'initial session is valid');
denied(fn()=>$market->secureAccount($supplier,['current_password'=>'wrong'],false),'revoking sessions requires current password');
$version=$market->secureAccount($supplier,['current_password'=>'DigiKonek!2026'],false);check(currentUser()===null,'session revocation invalidates old version');
$_SESSION['session_version']=$version;check(currentUser()!==null,'caller session can retain the new version');
denied(fn()=>$market->secureAccount($supplier,['current_password'=>'DigiKonek!2026','new_password'=>'AnotherPass!234','password_confirmation'=>'different'],true),'password confirmation mismatch rejected');
$version=$market->secureAccount($supplier,['current_password'=>'DigiKonek!2026','new_password'=>'AnotherPass!234','password_confirmation'=>'AnotherPass!234'],true);
check(currentUser()===null,'password change also invalidates older sessions');
denied(fn()=>$market->login('supplier@demo.test','DigiKonek!2026','password-test'),'old password no longer works');
check($market->login('supplier@demo.test','AnotherPass!234','password-test')===2,'new password works');

$adminPrefs=$common;unset($adminPrefs['notify_reviews']);$market->savePreferences($admin,$adminPrefs);
$adminCount=(int)row('SELECT COUNT(*) AS n FROM notifications WHERE user_id=3')['n'];
$market->saveReview($retailer,$reviewInput);
check((int)row('SELECT COUNT(*) AS n FROM notifications WHERE user_id=3')['n']===$adminCount,'administrator review preference suppresses real review event');
$market->savePreferences($admin,$common);$market->saveReview($retailer,$reviewInput);
check((int)row('SELECT COUNT(*) AS n FROM notifications WHERE user_id=3')['n']===$adminCount+1,'administrator receives enabled review alert');
